// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {DEP_BANK, LogFile} from "../src/DEP_BANK.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    DEP_BANK c;
    function setUp() public { c = new DEP_BANK(); }
    function testFuzz_property(uint256 depositAmt, uint256 collectAmt, uint256 minSum) public {
        vm.assume(depositAmt <= VALUE_CAP);
        depositAmt = bound(depositAmt, 0, type(uint96).max);
        collectAmt = bound(collectAmt, 0, type(uint96).max);
        minSum = bound(minSum, 0, type(uint96).max);

        Reverter rev = new Reverter();
        LogFile lf = new LogFile();
        c.SetLogFile(address(lf));
        c.SetMinSum(minSum);
        c.Initialized();

        address actor = address(rev);
        vm.deal(actor, depositAmt);
        vm.prank(actor);
        c.Deposit{value: depositAmt}();

        uint256 beforeBal = c.balances(actor);
        uint256 beforeActual = address(rev).balance;

        bool ok;
        vm.prank(actor);
        try c.Collect(collectAmt) { ok = true; } catch { ok = false; }

        uint256 afterBal = c.balances(actor);
        uint256 afterActual = address(rev).balance;

        if (ok && beforeBal >= minSum && beforeBal >= collectAmt) {
            assertTrue(afterBal + collectAmt == beforeBal && afterActual == beforeActual + collectAmt);
        } else {
            assertTrue(afterBal == beforeBal && afterActual == beforeActual);
        }
    }
}

contract Reverter {
    fallback() external payable { revert(); }
    receive() external payable { revert(); }
}
